import assert from "node:assert/strict";
import { brotliDecompressSync } from "node:zlib";
import { test } from "vitest";
import { canonicalJson, sha256 } from "../src/canonical-json.js";
import { verifyLayerAssemblyProposals,
  type LayerAssemblyVerificationInput } from "../src/layer-assembly-proposals.js";

// Deterministic synthetic fixture generated by Python worker. No project source.
const workerFixtureBrotliBase64 = "";
const workerResultHash = "1c13a6df5be885374473b9eeef2775489155c7dba99ef646f1265a4707a6c5ba";
const reviewHash = "d".repeat(64);

function workerJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(workerJson).join(",")}]`;
  if (value !== null && typeof value === "object") {
    const item = value as Record<string, unknown>;
    return `{${Object.keys(item).sort()
      .map((key) => `${JSON.stringify(key)}:${workerJson(item[key])}`).join(",")}}`;
  }
  return JSON.stringify(value);
}
function fixture(): LayerAssemblyVerificationInput {
  const f = JSON.parse(brotliDecompressSync(
    Buffer.from(workerFixtureBrotliBase64, "base64")).toString("utf8")) as any;
  return { objectId: f.objectId, inputManifestHash: f.inputManifestHash,
    sourceFiles: f.sources.map((source: any) => ({
      sourceFileId: source.sourceFileId, objectId: source.objectId,
      sha256: source.sha256, stages: source.stages,
      sourceReviewHash: reviewHash, sectionCode: source.sectionCode })),
    sourceReviews: Object.fromEntries(f.sources.map((source: any) => [source.sourceFileId,
      { sourceSha256: source.sha256, revisionStatus: source.revisionStatus,
        approvalStatus: source.approvalStatus, sectionCode: source.sectionCode,
        pageStages: source.pageStages, contentHash: reviewHash, decisionHash: reviewHash }])),
    textArtifacts: Object.fromEntries(f.textArtifacts.map((artifact: any) => [
      artifact.sourceFileId, { content_json: artifact,
        content_hash: sha256(canonicalJson(artifact)) }])),
    result: f.result };
}
function rehashResult(input: LayerAssemblyVerificationInput): void {
  const result = input.result as any;
  const { contentHash: _old, ...body } = result;
  result.contentHash = sha256(workerJson(body));
}

test("independently verifies Python layer assembly fixture with abstentions and caps", () => {
  const input = fixture();
  const result = input.result as any;
  assert.equal(result.contentHash, workerResultHash);
  assert.equal(verifyLayerAssemblyProposals(input), true);
  assert.deepEqual(result.codeRows.map((row: any) => [row.parameterCode, row.proposalCount,
    row.abstentionCount, row.ocrRequiredPageCount, row.truncatedProposalCount]),
  [["SPZU-032", 0, 0, 0, 0], ["AR-044", 26, 0, 1, 10], ["ZU-125", 1, 5, 1, 0]]);
  assert.equal(result.codeRows.every((row: any) => row.status === "ABSTAIN"
    && row.absenceConclusion === "NOT_AVAILABLE"), true);
  assert.equal(result.findingCount, null);
  assert.equal(result.parameterCoverage, null);
  assert.equal(result.codeRows[1].proposals.length, 16);
  assert.equal(result.codeRows[0].reasonCodes.includes("EXISTING_SITE_GP_TABLE_ROW_REVIEW"), true);
});

test("rejects rehashed forged locator, status, inferred value, and false-zero counters", () => {
  const changes: Array<(input: LayerAssemblyVerificationInput) => void> = [
    (input) => { (input.result as any).codeRows[2].proposals[0].roles.material.lineText = "fake"; },
    (input) => { (input.result as any).codeRows[1].proposals[0].roles.heading.bboxMilliPoints[0] += 1; },
    (input) => { (input.result as any).codeRows[2].proposals[0].rawThickness = "70 мм"; },
    (input) => { (input.result as any).codeRows[2].proposals[0].typeAssociationStatus = "VERIFIED"; },
    (input) => { (input.result as any).codeRows[1].status = "PASS"; },
    (input) => { (input.result as any).codeRows[1].ocrRequiredPageCount = 0; },
    (input) => { (input.result as any).codeRows[1].truncatedProposalCount = 0; },
    (input) => { (input.result as any).codeRows[2].abstentions = []; },
    (input) => { (input.result as any).codeRows[1].reasonCodes =
      (input.result as any).codeRows[1].reasonCodes.filter((r: string) => r !== "OVERSIZE_ANCHOR_LINE_DEFERRED"); },
    (input) => { (input.result as any).findingCount = 1; },
  ];
  for (const change of changes) {
    const input = fixture(); change(input); rehashResult(input);
    assert.equal(verifyLayerAssemblyProposals(input), false);
  }
});

test("rejects unapproved source, wrong stage or section, altered artifact, and cross-heading forgery", () => {
  const changes: Array<(input: LayerAssemblyVerificationInput) => void> = [
    (input) => { input.sourceReviews["F-AR"].approvalStatus = "UNAPPROVED"; },
    (input) => { input.sourceReviews["F-AR"].contentHash = "e".repeat(64); },
    (input) => { input.sourceFiles[1].stages = ["RD"]; },
    (input) => { input.sourceFiles[1].sectionCode = "OV"; },
    (input) => { input.textArtifacts["F-AR"].content_hash = "f".repeat(64); },
    (input) => { (input.textArtifacts["F-AR"].content_json as any).pages[3].quality.disposition = "TEXT_LAYER_CANDIDATE"; },
    (input) => { (input.result as any).codeRows[2].proposals[0].roles.type.lineText = "Тип 1"; },
    (input) => { input.inputManifestHash = "b".repeat(64); },
  ];
  for (const [index, change] of changes.entries()) {
    const input = fixture(); change(input);
    assert.equal(verifyLayerAssemblyProposals(input), false, `tamper ${index}`);
  }
});
